SELECT sessions.id, sessions.browser, COUNT(web_events.id) AS web_event_count, MIN(web_events.duration_sec) AS min_duration_sec, SUM(CASE WHEN web_events.page = '/cart' THEN web_events.duration_sec ELSE 0 END) AS cart_duration_sec FROM sessions LEFT JOIN web_events ON sessions.id = web_events.session_id WHERE web_events.session_id IN (8, 17) GROUP BY sessions.id, sessions.browser HAVING web_event_count >= 4;
